begin;
create table public.arena_alliance_reports(id uuid primary key default gen_random_uuid(),alliance_id uuid not null references public.arena_alliances(id)on delete cascade,reporter_id uuid references public.profiles(id)on delete set null,target_user_id uuid references public.profiles(id)on delete set null,message_id bigint references public.arena_alliance_chat_messages(id)on delete set null,reason text not null check(length(trim(reason))between 3 and 240),status text not null default'open'check(status in('open','resolved','dismissed')),reviewed_by uuid references public.profiles(id)on delete set null,created_at timestamptz not null default now());create table public.arena_alliance_mutes(alliance_id uuid not null references public.arena_alliances(id)on delete cascade,user_id uuid not null references public.profiles(id)on delete cascade,muted_by uuid references public.profiles(id)on delete set null,reason text not null,expires_at timestamptz not null,created_at timestamptz not null default now(),primary key(alliance_id,user_id));alter table public.arena_alliance_reports enable row level security;alter table public.arena_alliance_mutes enable row level security;revoke all on public.arena_alliance_reports,public.arena_alliance_mutes from anon,authenticated;
create or replace function public.arena_report_alliance_message(p_message_id bigint,p_reason text)returns uuid language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_target uuid;v_id uuid;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;select author_id into v_target from public.arena_alliance_chat_messages where id=p_message_id and alliance_id=v_alliance and deleted_at is null;if v_target is null or v_target=v_user then raise exception'invalid report';end if;insert into public.arena_alliance_reports(alliance_id,reporter_id,target_user_id,message_id,reason)values(v_alliance,v_user,v_target,p_message_id,left(trim(p_reason),240))returning id into v_id;return v_id;end;$$;
create or replace function public.arena_get_alliance_moderation()returns jsonb language plpgsql stable security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_role not in('founder','elder')then raise exception'manager required';end if;return jsonb_build_object('reports',(select coalesce(jsonb_agg(to_jsonb(x)order by created_at desc),'[]'::jsonb)from(select r.id,r.reason,r.message_id,r.target_user_id,r.created_at,coalesce(p.display_name,'Guardião')target_name from public.arena_alliance_reports r left join public.profiles p on p.id=r.target_user_id where r.alliance_id=v_alliance and r.status='open')x),'mutes',(select coalesce(jsonb_agg(to_jsonb(x)order by expires_at desc),'[]'::jsonb)from(select m.user_id,m.reason,m.expires_at,coalesce(p.display_name,'Guardião')display_name from public.arena_alliance_mutes m left join public.profiles p on p.id=m.user_id where m.alliance_id=v_alliance and m.expires_at>now())x));end;$$;
create or replace function public.arena_resolve_alliance_report(p_report_id uuid,p_action text)returns jsonb language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_role text;v_report public.arena_alliance_reports%rowtype;begin select alliance_id,role into v_alliance,v_role from public.arena_alliance_members where user_id=v_user;if v_role not in('founder','elder')or p_action not in('dismiss','delete','mute24h')then raise exception'manager required';end if;select*into v_report from public.arena_alliance_reports where id=p_report_id and alliance_id=v_alliance and status='open'for update;if not found then raise exception'report unavailable';end if;if p_action='delete'then update public.arena_alliance_chat_messages set deleted_at=now()where id=v_report.message_id;elsif p_action='mute24h'then insert into public.arena_alliance_mutes values(v_alliance,v_report.target_user_id,v_user,'Denúncia confirmada',now()+interval'24 hours',now())on conflict(alliance_id,user_id)do update set expires_at=excluded.expires_at,reason=excluded.reason,muted_by=v_user;end if;update public.arena_alliance_reports set status=case when p_action='dismiss'then'dismissed'else'resolved'end,reviewed_by=v_user where id=v_report.id;return jsonb_build_object('resolved',true);end;$$;
create or replace function public.arena_send_alliance_chat(p_body text,p_reply_to bigint default null)returns bigint language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_alliance uuid;v_id bigint;begin select alliance_id into v_alliance from public.arena_alliance_members where user_id=v_user;if exists(select 1 from public.arena_alliance_mutes where alliance_id=v_alliance and user_id=v_user and expires_at>now())then raise exception'member muted';end if;if exists(select 1 from public.arena_alliance_chat_messages where author_id=v_user and created_at>now()-interval'2 seconds')then raise exception'rate limited';end if;insert into public.arena_alliance_chat_messages(alliance_id,author_id,body,reply_to)values(v_alliance,v_user,trim(p_body),p_reply_to)returning id into v_id;return v_id;end;$$;
revoke all on function public.arena_report_alliance_message(bigint,text),public.arena_get_alliance_moderation(),public.arena_resolve_alliance_report(uuid,text)from public;grant execute on function public.arena_report_alliance_message(bigint,text),public.arena_get_alliance_moderation(),public.arena_resolve_alliance_report(uuid,text)to authenticated;commit;
